'use strict'

import soundManager from '../service/sound-manager'
import resource from '../resource'
import { SOUND_BOSS_SCREAM_1, SOUND_BOSS_SCREAM_2, SOUND_BOSS_SCREAM_3 } from '../constant'

// The screams of the bosses (the samples $10, $20, $40 of $0601), read in bank 0 $9B6F and measured: a scream keeps its
// bit in $05F6, and the sample starts again $A0 frames after the last one began ($05F2), every 160 frames (measured in
// the rooms of Aquamentus, Dodongo and Manhandla, and in the rooms next to them, as long as Link stays). It is asked
// as the boss is made ($9447, $9487, $A10C) and coming into a room next to it (see dungeon.js, screamOfBoss); $0603
// $80 ($9911) cuts it and clears $05F6, when the boss dies ($B010, measured for Aquamentus and Manhandla) and when Link
// leaves the room. In the ROM another sample (Link hurt, a door…) takes the channel and puts the timer back; not here
export const SCREAMS = { 1: SOUND_BOSS_SCREAM_1, 2: SOUND_BOSS_SCREAM_2, 3: SOUND_BOSS_SCREAM_3 }
const SCREAM_FRAMES = 0xa0
let scream

// The scream of the boss of that kind (1, 2, 3: map.room.scream), heard in that room
export function startScream (kind, map) {
  stopScream()
  scream = { sound: resource.getSound(SCREAMS[kind]), map, frames: SCREAM_FRAMES }
  soundManager.play(scream.sound)
}

export function stopScream () {
  if (scream?.sound) {
    soundManager.stop(scream.sound)
  }
  scream = undefined
}

// One frame of the game (see Game.process): out of its room, it stops
export function stepScream (map) {
  if (!scream) {
    return
  }
  if (scream.map !== map) {
    stopScream()
    return
  }
  if (--scream.frames <= 0) {
    scream.frames = SCREAM_FRAMES
    soundManager.play(scream.sound)
  }
}

export function screaming () {
  return !!scream
}
