'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { TILE_WIDTH, NES_PIXEL, DIRECTION_EAST, DIRECTION_WEST, DIRECTION_NORTH, ENEMY_KEESE_RED, SOUND_ENNEMY_HIT } from '../../constant'
import { STATE_SPAWNING, STATE_DYING, drawImage } from './common'
import { Walker } from './walker'
import { Keese } from './keese'

// The vire of the dungeons, read in the ROM (object $12, bank 4 $9D57) and measured in $12 of level 4. It walks as the
// darknut (see walker.js: $0B, 0.5 NES pixel a frame, turning at $80). Going east or west it hops: each frame its y
// takes what the table $9D8B gives for the NES pixels it went since the grid, up to 16 NES pixels high in the middle of
// the tile, back on the line at the next point (measured, the heights after each frame below). Up and down it glides.
// Its image changes every 10 frames ($FA89); going north, its back ($B0, $B2), else its front ($AC, $AE).
// A hit that does not kill it ($9DBD: the flash $04F0 set): the next frame it becomes two red keeses ($1C, $B195) in two
// free slots from the last, in their clouds (slot + 14 frames, measured: out 24 frames after the hit in slots 9 and 10),
// one enemy more in the room ($034E); it shows the death sparkle, not counted as killed
const HOP = [0, -3, -6, -8, -10, -11, -12, -13, -14, -14, -14, -15, -16, -16, -16, -16, -16, -15, -14, -14, -14, -13, -12, -11, -10, -8, -6, -3, 0, 0, 0, 0]
const IMAGE_FRAMES = 10
const SPLIT_CLOUD = 14
const SLOTS = 11
const KEESES = 2
const STATE_SPLITTING = 'splitting'
const mod = (value, divisor) => ((value % divisor) + divisor) % divisor

export class Vire extends Walker {
  constructor (type, x, y, direction, random = Math.random) {
    super(type, x, y, direction, random)
    this.lift = 0 // Its hop, in display pixels (negative: up)
    this.frames = 0
    this.uncounted = false // Cut in two: dead, but not killed
  }

  hit (link, weapon = {}) {
    const damage = weapon.damage ?? link.swordDamage
    if (this.life - damage <= 0) {
      super.hit(link, weapon)
      return
    }
    if (weapon.damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= damage
    soundManager.play(resource.getSound(SOUND_ENNEMY_HIT))
    this.setState(STATE_SPLITTING)
  }

  // Into two red keeses, in the free slots from the last one
  split (map) {
    const taken = new Set(map.activeEnemies.filter(enemy => !enemy.isDead).map(enemy => enemy.slot))
    for (let k = 0; k < KEESES; k++) {
      let slot = SLOTS
      while (taken.has(slot) && slot > 1) {
        slot--
      }
      taken.add(slot)
      const keese = new Keese(ENEMY_KEESE_RED, this.x, this.y, this.random)
      keese.slot = slot
      keese.cloudSteps = slot + SPLIT_CLOUD
      keese.setState(STATE_SPAWNING)
      map.activeEnemies.push(keese)
    }
    if (map.room) {
      map.enemyCount++
    }
    this.uncounted = true
    this.setState(STATE_DYING)
  }

  act (map, link) {
    this.frames++
    if (this.state === STATE_SPLITTING) {
      this.split(map)
      return
    }
    super.act(map, link)
  }

  // The hop goes with the pixels gone along the tile, east or west
  walk (map, link) {
    this.y -= this.lift
    super.walk(map, link)
    const along = this.direction === DIRECTION_EAST ? mod(this.x - map.x, TILE_WIDTH) : this.direction === DIRECTION_WEST ? mod(map.x - this.x, TILE_WIDTH) : 0
    this.lift = HOP[along] * NES_PIXEL
    this.y += this.lift
  }

  drawBody (context) {
    const name = this.direction === DIRECTION_NORTH ? 'vire_north' : 'vire_move'
    drawImage(context, resource.getSprite(name), Math.floor(this.frames / IMAGE_FRAMES) % 2, this.x, this.y, this.width, this.height)
  }
}
