'use strict'

import resource from '../../resource'
import { ENEMY_ARMOS, DIRECTION_NORTH, DIRECTION_SOUTH, NES_PIXEL } from '../../constant'
import { drawImage } from './common'
import { Walker } from './walker'

// The Armos, as measured in the ROM (object $1E, bank 4 $8CC7, $8D50; on 12,1): a statue Link walks into comes
// alive 3 NES pixels lower than the statue. For 63 frames it waits, blinking (drawn every other frame, from the
// frame after), harmful to touch but out of reach of the weapons; Link who woke it is hurt at once (he is on its
// square). Then it walks the grid as the chasers, first south ($98 = 4), slowly (0.5 NES pixel a frame) or fast
// (1.5), half the time each (its random byte under or from $80: $03BC = $20 or $60). Always red, 3 points of life,
// one heart at contact (see WALKERS). Its image changes every 6 frames of its own counter ($03D0, not while it is
// pushed back), the first one when it starts walking: from the front ($A0/$A2, $A4/$A6) but going north, from the
// back ($A8/$AA, $AC/$AE)
export const ARMOS_WAKE_STEPS = 63
export const ARMOS_BELOW_STATUE = 3 * NES_PIXEL
const SLOW_SPEED = 1
const FAST_SPEED = 3
const STATE_WAKING = 'waking'
const IMAGE_STEPS = 6

export class Armos extends Walker {
  // x, y: the statue
  constructor (x, y, random = Math.random) {
    super(ENEMY_ARMOS, x, y + ARMOS_BELOW_STATUE, DIRECTION_SOUTH, random)
    this.speed = random() < 0.5 ? SLOW_SPEED : FAST_SPEED
    this.imageSteps = 0
    this.setState(STATE_WAKING)
  }

  // Nothing reaches it while it waits
  get isVulnerable () {
    return this.state !== STATE_WAKING && super.isVulnerable
  }

  start (map) {
    super.start(map)
    this.direction = DIRECTION_SOUTH
  }

  // Waiting, it keeps facing south when it hurts Link
  turnBack () {
    if (this.state !== STATE_WAKING) {
      super.turnBack()
    }
  }

  act (map, link) {
    if (this.state === STATE_WAKING) {
      if (this.steps >= ARMOS_WAKE_STEPS) {
        this.start(map)
      }
      return
    }
    this.imageSteps++
    super.act(map, link)
  }

  // The image of its walk: the second one first (see above); the first one while it waits
  get image () {
    return this.state === STATE_WAKING ? 0 : (Math.floor((this.imageSteps - 1) / IMAGE_STEPS) + 1) % 2
  }

  drawBody (context) {
    if (this.state === STATE_WAKING && this.steps % 2 === 0) {
      return
    }
    const side = this.direction === DIRECTION_NORTH ? 'north' : 'south'
    drawImage(context, resource.getSprite(`armos_${side}_move`), this.image, this.x, this.y, this.width, this.height)
  }
}
