'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { overlaps } from '../../utils/box'
import { ITEM_SHIELD_NORMAL, SOUND_ENNEMY_HIT } from '../../constant'
import { STATE_DYING, STATE_DEAD, FLASH_STEPS, drawImage } from './common'
import { Walker } from './walker'

// The like like of the dungeons, read in the ROM (object $17, bank 4 $9CC9) and measured in $32 of level 4. It walks as
// the darknut (see walker.js: 0.5 NES pixel a frame, turning at $80), its image going 0 to 3 every 8 frames ($03D0):
// tiles $A6, $A4, $A2, $A4. Touching Link, it takes a heart and swallows him: it is put on him ($9CF8), stands still,
// and Link no longer moves ($0512), hidden under it, but may strike; its image starts again at 0 and goes up every 4
// frames to 3, where it stays. Its counter ($042C) goes up each frame: at $60 (96 frames, measured), Link loses the
// magical shield ($0676), and it goes back to $C0 each frame after ($9D2A): it lets him go only when it dies ($9D4A,
// measured on 1300 frames). 9 hits of the wooden sword ($90)
const IMAGE_FRAMES = 8
const HOLD_IMAGE_FRAMES = 4
const LAST_IMAGE = 3
const SHIELD_FRAMES = 0x60
// The images 0 to 3 of the ROM in the frames of the sprite ($A2, $A4, $A6)
const IMAGES = [2, 1, 0, 1]

export class LikeLike extends Walker {
  constructor (type, x, y, direction, random = Math.random) {
    super(type, x, y, direction, random)
    this.frames = 0
    this.holding = undefined // Link, swallowed
    this.holdFrames = 0
  }

  // Its counter is 1 the frame it catches him (measured: the shield gone 95 frames later)
  swallow (link) {
    this.holding = link
    this.holdFrames = 1
    this.x = link.x
    this.y = link.y
    link.knockback = undefined
    link.swallowed = this
    link.stopWalking()
  }

  release () {
    if (this.holding?.swallowed === this) {
      this.holding.swallowed = undefined
    }
    this.holding = undefined
  }

  // Holding Link, a hit does not push it away from him
  hit (link, weapon = {}) {
    if (!this.holding) {
      super.hit(link, weapon)
      return
    }
    if (weapon.damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= weapon.damage ?? link.swordDamage
    if (this.life <= 0) {
      this.release()
      super.hit(link, { ...weapon, damage: 0 })
      return
    }
    soundManager.play(resource.getSound(SOUND_ENNEMY_HIT))
    this.flashSteps = FLASH_STEPS
    this.flashType = link.map?.type
  }

  fight (map, link) {
    if (this.isHitByBlade(link)) {
      this.hitByBlade(link)
      return
    }
    if (this.holding || link.swallowed || !this.isActive || map.frozen) {
      return
    }
    if (overlaps(this.getBox(), link.getContactBox()) && link.hurt(this.contactDamage, this.getBox())) {
      this.swallow(link)
    }
  }

  process (map, link) {
    super.process(map, link)
    if (this.holding && (this.state === STATE_DYING || this.state === STATE_DEAD)) {
      this.release()
    }
  }

  act (map, link) {
    this.frames++
    if (!this.holding) {
      super.act(map, link)
      return
    }
    this.holdFrames++
    if (this.holdFrames === SHIELD_FRAMES && this.holding.inventory) {
      this.holding.inventory.shield = ITEM_SHIELD_NORMAL
    }
  }

  get image () {
    if (this.holding) {
      return Math.min(LAST_IMAGE, Math.floor(this.holdFrames / HOLD_IMAGE_FRAMES))
    }
    return Math.floor(this.frames / IMAGE_FRAMES) % IMAGES.length
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('like_like'), IMAGES[this.image], this.x, this.y, this.width, this.height)
  }
}
